#[summary("clamp task")]
mod tasks {
    #[effects(pure)]
    #[uses(is_clamped, valid_range)]
    fn clamp(x: i64, lo: i64, hi: i64) -> (r: i64)
        requires valid_range(lo, hi),
        ensures is_clamped(x, lo, hi, r),
    {
        if x < lo {
            lo
        } else if x > hi {
            hi
        } else {
            x
        }
    }

    spec fn is_clamped(x: i64, lo: i64, hi: i64, r: i64) -> bool {
        x < lo && r == lo || x > hi && r == hi || lo <= x && x <= hi && r == x
    }

    spec fn valid_range(lo: i64, hi: i64) -> bool {
        lo <= hi
    }
}

#[summary("task implementations")]
mod tasks {
    spec fn is_floor_mid(a: i64, b: i64, r: i64) -> bool {
        2 * r <= a + b && a + b < 2 * r + 2
    }

    #[effects(pure)]
    #[uses(is_floor_mid)]
    fn midpoint(a: i64, b: i64) -> (r: i64)
        ensures is_floor_mid(a, b, r),
    {
        let qa: i64 = a / 2;
        let qb: i64 = b / 2;
        let ra: i64 = a % 2;
        let rb: i64 = b % 2;
        let s: i64 = ra + rb;
        let adj: i64 = if s >= 2 {
            1
        } else {
            if s >= 0 {
                0
            } else {
                -1
            }
        };
        qa + qb + adj
    }
}

#[summary("saturating sum")]
mod tasks {
    #[uses(prefix)]
    spec fn is_prefix(a: &[i64], n: usize, s: i64) -> bool {
        n <= a.len() && s == prefix(a, n)
    }

    #[uses(prefix)]
    spec fn is_total(a: &[i64], r: i64) -> bool {
        r == prefix(a, a.len())
    }

    #[uses(sat_add)]
    spec fn prefix(a: &[i64], n: usize) -> i64
        decreases n,
    {
        if n == 0 {
            0
        } else if n > a.len() {
            0
        } else {
            sat_add(prefix(a, n - 1), a[n - 1])
        }
    }

    spec fn sat_add(s: i64, x: i64) -> i64 {
        if s + x > i64::MAX {
            i64::MAX
        } else if s + x < i64::MIN {
            i64::MIN
        } else {
            s + x
        }
    }

    #[effects(pure)]
    #[uses(is_prefix, is_total, prefix, sat_add)]
    fn sat_sum(a: &[i64]) -> (r: i64)
        ensures is_total(a, r),
    {
        let mut s: i64 = 0;
        let mut i: usize = 0;
        while i < a.len()
            invariant is_prefix(a, i, s),
            decreases a.len() - i,
        {
            let x: i64 = a[i];
            if x > 0 && s > i64::MAX - x {
                s = i64::MAX;
            } else if x < 0 && s < i64::MIN - x {
                s = i64::MIN;
            } else {
                s = s + x;
            }
            i = i + 1;
        }
        s
    }
}

#[summary("count elements in an inclusive range")]
mod tasks {
    spec fn cnt(a: &[i64], lo: i64, hi: i64, n: usize) -> usize
        decreases n,
    {
        if n == 0 {
            0
        } else if n <= a.len() && lo <= a[n - 1] && a[n - 1] <= hi {
            cnt(a, lo, hi, n - 1) + 1
        } else {
            cnt(a, lo, hi, n - 1)
        }
    }

    #[effects(pure)]
    #[uses(cnt, is_count, loop_inv)]
    fn count_in_range(a: &[i64], lo: i64, hi: i64) -> (r: usize)
        ensures is_count(a, lo, hi, r),
    {
        let mut i: usize = 0;
        let mut c: usize = 0;
        while i < a.len()
            invariant loop_inv(a, lo, hi, i, c),
            decreases a.len() - i,
        {
            if lo <= a[i] && a[i] <= hi {
                c = c + 1;
            }
            i = i + 1;
        }
        c
    }

    spec fn is_count(a: &[i64], lo: i64, hi: i64, r: usize) -> bool {
        r == cnt(a, lo, hi, a.len())
    }

    spec fn loop_inv(a: &[i64], lo: i64, hi: i64, i: usize, c: usize) -> bool {
        i <= a.len() && c <= i && c == cnt(a, lo, hi, i)
    }
}

#[summary("first maximum index")]
mod tasks {
    #[effects(pure)]
    #[uses(is_first_max, nonempty, scan_inv)]
    fn first_max_index(a: &[i64]) -> (r: usize)
        requires nonempty(a),
        ensures is_first_max(a, r),
    {
        let mut best: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant scan_inv(a, i, best),
            decreases a.len() - i,
        {
            if a[i] > a[best] {
                best = i;
            }
            i = i + 1;
        }
        best
    }

    spec fn is_first_max(a: &[i64], r: usize) -> bool {
        r < a.len() && (forall|j: usize| j < a.len() ==> #[trigger] a[j] <= a[r]) && (forall|k: usize| k < r ==> #[trigger] a[k] < a[r])
    }

    spec fn nonempty(a: &[i64]) -> bool {
        a.len() > 0
    }

    spec fn scan_inv(a: &[i64], i: usize, best: usize) -> bool {
        best < i && i <= a.len() && (forall|j: usize| j < i ==> #[trigger] a[j] <= a[best]) && (forall|k: usize| k < best ==> #[trigger] a[k] < a[best])
    }
}

#[summary("last minimum index")]
mod tasks {
    spec fn is_last_min(a: &[i64], r: usize) -> bool {
        r < a.len() && (forall|j: usize| j < a.len() ==> a[r] <= #[trigger] a[j]) && (forall|k: usize| r < k && k < a.len() ==> a[r] < #[trigger] a[k])
    }

    #[effects(pure)]
    #[uses(is_last_min, last_min_upto, nonempty)]
    fn last_min_index(a: &[i64]) -> (r: usize)
        requires nonempty(a),
        ensures is_last_min(a, r),
    {
        let mut best: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant last_min_upto(a, i, best),
            decreases a.len() - i,
        {
            if a[i] <= a[best] {
                best = i;
            }
            i = i + 1;
        }
        best
    }

    spec fn last_min_upto(a: &[i64], i: usize, r: usize) -> bool {
        i <= a.len() && r < i && (forall|j: usize| j < i ==> a[r] <= #[trigger] a[j]) && (forall|k: usize| r < k && k < i ==> a[r] < #[trigger] a[k])
    }

    spec fn nonempty(a: &[i64]) -> bool {
        a.len() > 0
    }
}

#[summary("strictly increasing check")]
mod tasks {
    spec fn is_strictly_increasing(a: &[i64], r: bool) -> bool {
        r == (forall|j: usize| j + 1 < a.len() ==> #[trigger] a[j] < a[j + 1])
    }

    spec fn loop_inv(a: &[i64], i: usize, ok: bool) -> bool {
        i < a.len() && ok == (forall|j: usize| j < i ==> #[trigger] a[j] < a[j + 1])
    }

    #[effects(pure)]
    #[uses(is_strictly_increasing, loop_inv)]
    fn strictly_increasing(a: &[i64]) -> (r: bool)
        ensures is_strictly_increasing(a, r),
    {
        if a.len() == 0 {
            true
        } else {
            let mut ok: bool = true;
            let mut i: usize = 0;
            while i + 1 < a.len()
                invariant loop_inv(a, i, ok),
                decreases a.len() - i,
            {
                ok = ok && a[i] < a[i + 1];
                i = i + 1;
            }
            ok
        }
    }
}

#[summary("binary search lower_bound")]
mod tasks {
    spec fn bounds(a: &[i64], t: i64, lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len() && (forall|k: usize| k < lo ==> #[trigger] a[k] < t) && (forall|m: usize| hi <= m && m < a.len() ==> #[trigger] a[m] >= t)
    }

    spec fn is_lower_bound(a: &[i64], t: i64, r: usize) -> bool {
        r <= a.len() && (forall|k: usize| k < r ==> #[trigger] a[k] < t) && (forall|m: usize| r <= m && m < a.len() ==> #[trigger] a[m] >= t)
    }

    #[effects(pure)]
    #[uses(bounds, is_lower_bound, sorted)]
    fn lower_bound(a: &[i64], t: i64) -> (r: usize)
        requires sorted(a),
        ensures is_lower_bound(a, t, r),
    {
        let mut lo: usize = 0;
        let mut hi: usize = a.len();
        while lo < hi
            invariant bounds(a, t, lo, hi),
            decreases hi - lo,
        {
            let mid: usize = lo + (hi - lo) / 2;
            if a[mid] < t {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        lo
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|i: usize, j: usize| i <= j && j < a.len() ==> #[trigger] a[i] <= #[trigger] a[j]
    }
}

#[summary("floor division")]
mod tasks {
    #[effects(pure)]
    #[uses(is_floor_div, valid_input)]
    fn div_floor(a: i64, b: i64) -> (r: i64)
        requires valid_input(a, b),
        ensures is_floor_div(a, b, r),
    {
        let q: i64 = a / b;
        let m: i64 = a % b;
        if m != 0 && (m < 0) != (b < 0) {
            q - 1
        } else {
            q
        }
    }

    spec fn is_floor_div(a: i64, b: i64, r: i64) -> bool {
        if b > 0 {
            r * b <= a && a < r * b + b
        } else {
            r * b >= a && a > r * b + b
        }
    }

    spec fn valid_input(a: i64, b: i64) -> bool {
        b != 0 && !(a == -9223372036854775808 && b == -1)
    }
}

#[summary("floor-division remainder")]
mod tasks {
    spec fn is_mod_floor(a: i64, b: i64, r: i64) -> bool {
        r == (if a % b != 0 && (a % b < 0) != (b < 0) { a % b + b } else { a % b })
    }

    #[effects(pure)]
    #[uses(is_mod_floor, nonzero, sign_ok)]
    fn mod_floor(a: i64, b: i64) -> (r: i64)
        requires nonzero(b),
        ensures is_mod_floor(a, b, r), sign_ok(b, r),
    {
        if b == -1 {
            0
        } else {
            let t: i64 = a % b;
            if t != 0 && (t < 0) != (b < 0) {
                t + b
            } else {
                t
            }
        }
    }

    spec fn nonzero(b: i64) -> bool {
        b != 0
    }

    spec fn sign_ok(b: i64, r: i64) -> bool {
        (b > 0 ==> 0 <= r && r < b) && (b < 0 ==> b < r && r <= 0)
    }
}

#[summary("maximum subarray sum (Kadane)")]
mod tasks {
    spec fn achieved(a: &[i64], w: &[usize], r: i64) -> bool {
        w.len() == 2 && w[0] < w[1] && w[1] <= a.len() && seg_sum(a, w[0], w[1]) == r
    }

    spec fn in_domain(a: &[i64]) -> bool {
        a.len() >= 1 && a.len() <= 1000000 && (forall|k: usize| k < a.len() ==> -1000000000 <= #[trigger] a[k] && a[k] <= 1000000000)
    }

    spec fn is_upper(a: &[i64], r: i64) -> bool {
        forall|lo: usize, hi: usize| lo < hi && hi <= a.len() ==> #[trigger] seg_sum(a, lo, hi) <= r
    }

    #[effects(pure)]
    #[uses(achieved, in_domain, is_upper, len2, loop_inv, seg_sum)]
    fn kadane(a: &[i64], w: &mut [usize]) -> (r: i64)
        requires in_domain(a), len2(w),
        ensures is_upper(a, r), achieved(a, w, r),
    {
        let n: usize = a.len();
        let mut cur: i64 = a[0];
        let mut best: i64 = a[0];
        let mut cl: usize = 0;
        let mut bl: usize = 0;
        let mut bh: usize = 1;
        let mut i: usize = 1;
        while i < n
            invariant n == a.len(), in_domain(a), loop_inv(a, i, cur, best, cl, bl, bh),
            decreases n - i,
        {
            let x: i64 = a[i];
            if cur > 0 {
                cur = cur + x;
            } else {
                cur = x;
                cl = i;
            }
            i = i + 1;
            if cur > best {
                best = cur;
                bl = cl;
                bh = i;
            }
        }
        w[0] = bl;
        w[1] = bh;
        best
    }

    spec fn len2(w: &[usize]) -> bool {
        w.len() == 2
    }

    spec fn loop_inv(a: &[i64], i: usize, cur: i64, best: i64, cl: usize, bl: usize, bh: usize) -> bool {
        1 <= i && i <= a.len() && -1000000000 <= cur && cur <= 1000000000 * i && cur <= best && cl < i && seg_sum(a, cl, i) == cur && bl < bh && bh <= i && seg_sum(a, bl, bh) == best && (forall|p: usize| p < i ==> #[trigger] seg_sum(a, p, i) <= cur) && (forall|p2: usize, q2: usize| p2 < q2 && q2 <= i ==> #[trigger] seg_sum(a, p2, q2) <= best)
    }

    #[effects(pure)]
    #[uses(len2)]
    fn max_subarray(a: &[i64]) -> (r: i64)
        requires in_domain(a),
        ensures is_upper(a, r),
    {
        let mut w: [usize; 2] = [0, 0];
        kadane(a, &mut w)
    }

    spec fn seg_sum(a: &[i64], lo: usize, hi: usize) -> i64
        decreases hi,
    {
        if hi <= lo {
            0
        } else {
            seg_sum(a, lo, hi - 1) + a[hi - 1]
        }
    }
}

#[summary("second largest distinct value")]
mod tasks {
    spec fn contains(a: &[i64], n: usize, v: i64) -> bool
        decreases n,
    {
        n > 0 && n <= a.len() && (a[n - 1] == v || contains(a, n - 1, v))
    }

    spec fn has_greater(a: &[i64], n: usize, v: i64) -> bool
        decreases n,
    {
        n > 0 && n <= a.len() && (a[n - 1] > v || has_greater(a, n - 1, v))
    }

    spec fn inv(a: &[i64], i: usize, m1: i64, m2: i64) -> bool {
        i <= a.len() && (forall|j: usize| j < i ==> #[trigger] a[j] <= m1) && (m1 == i64::MIN || contains(a, i, m1)) && (forall|v: i64| v < m1 ==> #[trigger] has_greater(a, i, v)) && (forall|q: usize| q < i && #[trigger] a[q] < m1 ==> a[q] <= m2) && (m2 == i64::MIN || contains(a, i, m2) && m2 < m1)
    }

    spec fn is_second_max(a: &[i64], r: i64) -> bool {
        (forall|j: usize, k: usize| j < a.len() && k < a.len() && #[trigger] a[j] < #[trigger] a[k] ==> a[j] <= r) && (r == i64::MIN || contains(a, a.len(), r) && has_greater(a, a.len(), r))
    }

    #[effects(pure)]
    #[uses(contains, has_greater, inv, is_second_max)]
    fn second_max(a: &[i64]) -> (r: i64)
        ensures is_second_max(a, r),
    {
        let mut m1: i64 = i64::MIN;
        let mut m2: i64 = i64::MIN;
        let mut i: usize = 0;
        while i < a.len()
            invariant inv(a, i, m1, m2),
            decreases a.len() - i,
        {
            let x: i64 = a[i];
            if x > m1 {
                m2 = m1;
                m1 = x;
            } else if x < m1 && x > m2 {
                m2 = x;
            }
            i = i + 1;
        }
        m2
    }
}

#[summary("in-place right rotation of an i64 slice")]
mod tasks {
    spec fn range_ok(a: &[i64], lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len()
    }

    spec fn rev_inv(a: &[i64], o: &[i64], lo: usize, hi: usize, i: usize, j: usize) -> bool {
        a.len() == o.len() && lo <= i && i <= j && j <= hi && hi <= a.len() && i + j == lo + hi && (forall|m: usize| lo <= m && m < i ==> #[trigger] a[m] == o[lo + hi - 1 - m]) && (forall|p: usize| j <= p && p < hi ==> #[trigger] a[p] == o[lo + hi - 1 - p]) && (forall|q: usize| q < a.len() && (q < lo || hi <= q || i <= q && q < j) ==> #[trigger] a[q] == o[q])
    }

    #[effects(pure)]
    #[uses(range_ok, rev_inv, reversed_range)]
    fn reverse_range(a: &mut [i64], lo: usize, hi: usize) -> ()
        requires range_ok(a, lo, hi),
        ensures reversed_range(a, old(a), lo, hi),
    {
        let mut i: usize = lo;
        let mut j: usize = hi;
        while i + 1 < j
            invariant rev_inv(a, old(a), lo, hi, i, j),
            decreases j - i,
        {
            let t: i64 = a[i];
            a[i] = a[j - 1];
            a[j - 1] = t;
            i = i + 1;
            j = j - 1;
        }
    }

    spec fn reversed_range(a: &[i64], o: &[i64], lo: usize, hi: usize) -> bool {
        a.len() == o.len() && lo <= hi && hi <= a.len() && (forall|m: usize| lo <= m && m < hi ==> #[trigger] a[m] == o[lo + hi - 1 - m]) && (forall|p: usize| p < a.len() && (p < lo || hi <= p) ==> #[trigger] a[p] == o[p])
    }

    #[effects(pure)]
    #[uses(range_ok, reversed_range, rotated)]
    fn rotate_right(a: &mut [i64], k: usize) -> ()
        ensures rotated(a, old(a), k),
    {
        let n: usize = a.len();
        if n > 0 {
            let s: usize = k % n;
            reverse_range(a, 0, n);
            reverse_range(a, 0, s);
            reverse_range(a, s, n);
        }
    }

    spec fn rotated(a: &[i64], o: &[i64], k: usize) -> bool {
        a.len() == o.len() && (o.len() == 0 || (forall|m: usize| m < k % o.len() ==> #[trigger] a[m] == o[m + o.len() - k % o.len()]) && (forall|p: usize| k % o.len() <= p && p < o.len() ==> #[trigger] a[p] == o[p - k % o.len()]))
    }
}

#[summary("dedup of sorted slices in place")]
mod tasks {
    spec fn bound(a: &[i64], r: usize) -> bool {
        r <= a.len()
    }

    spec fn cnt(b: &[i64], k: usize) -> usize
        decreases k,
    {
        if k == 0 {
            0
        } else if k == 1 {
            1
        } else if b[k - 1] != b[k - 2] {
            cnt(b, k - 1) + 1
        } else {
            cnt(b, k - 1)
        }
    }

    spec fn cnt_is(b: &[i64], i: usize, w: usize) -> bool {
        w == cnt(b, i)
    }

    spec fn cnt_le(b: &[i64], i: usize, w: usize) -> bool {
        forall|k: usize| k < i ==> 1 <= cnt(b, k + 1) && cnt(b, k + 1) <= w && #[trigger] b[k] == b[k]
    }

    #[effects(pure)]
    #[uses(bound, cnt, cnt_is, cnt_le, last, len_eq, maps, same_from, sorted, strict, zeros_range)]
    fn dedup_sorted(a: &mut [i64]) -> (r: usize)
        requires sorted(a),
        ensures len_eq(a, old(a)), bound(a, r), cnt_is(old(a), old(a).len(), r), strict(a, r), maps(a, old(a), old(a).len()), zeros_range(a, r, a.len()),
    {
        let n: usize = a.len();
        let mut w: usize = 0;
        let mut i: usize = 0;
        while i < n
            invariant n == a.len(), len_eq(a, old(a)), w <= i, i <= n, sorted(old(a)), strict(a, w), last(a, w, old(a), i), cnt_is(old(a), i, w), cnt_le(old(a), i, w), maps(a, old(a), i), zeros_range(a, w, i), same_from(a, old(a), i),
            decreases n - i,
        {
            let v: i64 = a[i];
            if w == 0 || v != a[w - 1] {
                a[w] = v;
                if w != i {
                    a[i] = 0;
                }
                w = w + 1;
            } else {
                a[i] = 0;
            }
            i = i + 1;
        }
        w
    }

    spec fn last(a: &[i64], w: usize, b: &[i64], i: usize) -> bool {
        i == 0 && w == 0 || i > 0 && w > 0 && a[w - 1] == b[i - 1]
    }

    spec fn len_eq(a: &[i64], b: &[i64]) -> bool {
        a.len() == b.len()
    }

    spec fn maps(a: &[i64], b: &[i64], i: usize) -> bool {
        forall|k: usize| k < i ==> a[cnt(b, k + 1) - 1] == #[trigger] b[k]
    }

    spec fn same_from(a: &[i64], b: &[i64], i: usize) -> bool {
        forall|k: usize| i <= k && k < a.len() ==> #[trigger] a[k] == b[k]
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|i: usize| i + 1 < a.len() ==> #[trigger] a[i] <= a[i + 1]
    }

    spec fn strict(a: &[i64], n: usize) -> bool {
        forall|i: usize, j: usize| i < j && j < n ==> #[trigger] a[i] < #[trigger] a[j]
    }

    spec fn zeros_range(a: &[i64], lo: usize, hi: usize) -> bool {
        forall|k: usize| lo <= k && k < hi ==> #[trigger] a[k] == 0
    }
}

#[summary("move zeros to the end, stable for non-zeros")]
mod tasks {
    spec fn count_is(o: &[i64], i: usize, j: usize) -> bool {
        nzc(o, i) == j
    }

    #[effects(pure)]
    #[uses(count_is, nzc, placed, placed_below, result_ok, same_len, suffix_same, zeros_from)]
    fn move_zeros(a: &mut [i64]) -> ()
        ensures result_ok(old(a), a),
    {
        let n: usize = a.len();
        let mut i: usize = 0;
        let mut j: usize = 0;
        while i < n
            invariant n == a.len(), same_len(old(a), a), j <= i, i <= n, count_is(old(a), i, j), placed(old(a), a, i), placed_below(old(a), i, j), suffix_same(old(a), a, i),
            decreases n - i,
        {
            let v: i64 = a[i];
            if v != 0 {
