#[summary("gcd of absolute values")]
mod tasks {
    spec fn abs_v(x: i64) -> i64 {
        if x < 0 {
            -x
        } else {
            x
        }
    }

    #[effects(pure)]
    #[uses(abs_v, is_gcd, loop_inv, not_min, sgcd)]
    fn gcd(a: i64, b: i64) -> (r: i64)
        requires not_min(a), not_min(b),
        ensures is_gcd(a, b, r),
    {
        let mut x: i64 = if a < 0 {
            -a
        } else {
            a
        };
        let mut y: i64 = if b < 0 {
            -b
        } else {
            b
        };
        while y != 0
            invariant loop_inv(a, b, x, y),
            decreases y,
        {
            let t: i64 = x % y;
            x = y;
            y = t;
        }
        x
    }

    spec fn is_gcd(a: i64, b: i64, r: i64) -> bool {
        r >= 0 && r == sgcd(abs_v(a), abs_v(b))
    }

    spec fn loop_inv(a: i64, b: i64, x: i64, y: i64) -> bool {
        x >= 0 && y >= 0 && sgcd(x, y) == sgcd(abs_v(a), abs_v(b))
    }

    spec fn not_min(a: i64) -> bool {
        a > -9223372036854775807 - 1
    }

    spec fn sgcd(x: i64, y: i64) -> i64
        decreases y,
    {
        if y <= 0 {
            x
        } else {
            sgcd(y, x % y)
        }
    }
}

#[summary("integer square root")]
mod tasks {
    spec fn is_isqrt(n: i64, r: i64) -> bool {
        r >= 0 && r * r <= n && (r + 1) * (r + 1) > n
    }

    #[effects(pure)]
    #[uses(is_isqrt, nonneg, search_inv)]
    fn isqrt(n: i64) -> (r: i64)
        requires nonneg(n),
        ensures is_isqrt(n, r),
    {
        let mut lo: i64 = 0;
        let mut hi: i64 = 3037000500;
        while hi - lo > 1
            invariant search_inv(n, lo, hi),
            decreases hi - lo,
        {
            let mid: i64 = lo + (hi - lo) / 2;
            if mid <= 3037000499 && mid * mid <= n {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        lo
    }

    spec fn nonneg(n: i64) -> bool {
        n >= 0
    }

    spec fn search_inv(n: i64, lo: i64, hi: i64) -> bool {
        0 <= lo && lo < hi && hi <= 3037000500 && lo * lo <= n && hi * hi > n
    }
}

#[summary("digit counting")]
mod tasks {
    spec fn abs_digits(n: i64, r: i64) -> bool {
        if n < 0 {
            digits_of(-n, r)
        } else {
            digits_of(n, r)
        }
    }

    #[effects(pure)]
    #[uses(digits_i64, digits_of, nonneg, small)]
    fn cd(m: i64) -> (r: i64)
        requires nonneg(m),
        ensures digits_i64(m, r), small(m, r),
        decreases m,
    {
        if m < 10 {
            1
        } else {
            1 + cd(m / 10)
        }
    }

    #[effects(pure)]
    #[uses(abs_digits, digits_i64, digits_of, nonneg, small)]
    fn count_digits(n: i64) -> (r: i64)
        ensures abs_digits(n, r),
    {
        if n < -9223372036854775807 {
            1 + cd(922337203685477580)
        } else if n < 0 {
            cd(-n)
        } else {
            cd(n)
        }
    }

    spec fn digits_i64(m: i64, r: i64) -> bool {
        digits_of(m, r)
    }

    spec fn digits_of(m: u64, r: i64) -> bool
        decreases m,
    {
        if m < 10 {
            r == 1
        } else {
            digits_of(m / 10, r - 1)
        }
    }

    spec fn nonneg(m: i64) -> bool {
        m >= 0
    }

    spec fn small(m: i64, r: i64) -> bool {
        r >= 1 && r <= m + 1
    }
}

#[summary("range sum task")]
mod tasks {
    spec fn inv(a: &[i64], i: usize, j: usize, k: usize, s: i64) -> bool {
        i <= k && k <= j && s == seg(a, k, j) && -1000000000000 * (j - k) <= s && s <= 1000000000000 * (j - k)
    }

    spec fn is_sum(a: &[i64], i: usize, j: usize, r: i64) -> bool {
        r == seg(a, i, j)
    }

    #[effects(pure)]
    #[uses(inv, is_sum, seg, valid)]
    fn range_sum(a: &[i64], i: usize, j: usize) -> (r: i64)
        requires valid(a, i, j),
        ensures is_sum(a, i, j, r),
    {
        let mut s: i64 = 0;
        let mut k: usize = j;
        while k > i
            invariant valid(a, i, j), inv(a, i, j, k, s),
            decreases k - i,
        {
            k = k - 1;
            s = s + a[k];
        }
        s
    }

    spec fn seg(a: &[i64], i: usize, j: usize) -> i64
        decreases j - i,
    {
        if i >= j || j > a.len() {
            0
        } else {
            a[i] + seg(a, i + 1, j)
        }
    }

    spec fn valid(a: &[i64], i: usize, j: usize) -> bool {
        i <= j && j <= a.len() && a.len() <= 1000000 && (forall|k: usize| k < a.len() ==> -1000000000000 <= #[trigger] a[k] && a[k] <= 1000000000000)
    }
}

#[summary("majority element")]
mod tasks {
    spec fn count(a: &[i64], x: i64, n: usize) -> usize
        decreases n,
    {
        if n == 0 || n > a.len() {
            0
        } else {
            count(a, x, n - 1) + (if a[n - 1] == x { 1 } else { 0 })
        }
    }

    spec fn count_all(a: &[i64], x: i64, c: usize) -> bool {
        c == count(a, x, a.len()) && c <= a.len()
    }

    #[effects(pure)]
    #[uses(count, count_all, count_upto)]
    fn count_occ(a: &[i64], x: i64) -> (r: usize)
        ensures count_all(a, x, r),
    {
        let n: usize = a.len();
        let mut j: usize = 0;
        let mut c: usize = 0;
        while j < n
            invariant count_upto(a, x, j, c), n == a.len(),
            decreases n - j,
        {
            if a[j] == x {
                c = c + 1;
            }
            j = j + 1;
        }
        c
    }

    spec fn count_upto(a: &[i64], x: i64, j: usize, c: usize) -> bool {
        j <= a.len() && c == count(a, x, j) && c <= j
    }

    spec fn found_ok(a: &[i64], found: bool, res: i64) -> bool {
        found ==> is_maj(a, res)
    }

    spec fn is_maj(a: &[i64], x: i64) -> bool {
        count(a, x, a.len()) > a.len() - count(a, x, a.len()) && count(a, x, a.len()) <= a.len()
    }

    #[effects(pure)]
    #[uses(count_all, found_ok, is_maj, majority_post, none_before, not_found_res)]
    fn majority(a: &[i64]) -> (r: i64)
        ensures majority_post(a, r),
    {
        let n: usize = a.len();
        let mut i: usize = 0;
        let mut found: bool = false;
        let mut res: i64 = i64::MIN;
        while i < n && !found
            invariant none_before(a, i, found), found_ok(a, found, res), not_found_res(found, res), n == a.len(),
            decreases n - i,
        {
            let x: i64 = a[i];
            let c: usize = tasks::count_occ(a, x);
            if c > n - c {
                res = x;
                found = true;
            }
            i = i + 1;
        }
        res
    }

    spec fn majority_post(a: &[i64], r: i64) -> bool {
        is_maj(a, r) || r == i64::MIN && (forall|k: usize| k < a.len() ==> !is_maj(a, #[trigger] a[k]))
    }

    spec fn none_before(a: &[i64], i: usize, found: bool) -> bool {
        i <= a.len() && (found || (forall|k: usize| k < i ==> !is_maj(a, #[trigger] a[k])))
    }

    spec fn not_found_res(found: bool, res: i64) -> bool {
        found || res == i64::MIN
    }
}

#[summary("longest run of equal consecutive elements")]
mod tasks {
    spec fn all_eq(a: &[i64], s: usize, e: usize) -> bool {
        s <= e && e <= a.len() && (forall|k: usize| s <= k && k < e ==> #[trigger] a[k] == a[s])
    }

    spec fn has_run(a: &[i64], r: usize) -> bool {
        !(forall|s: usize, e: usize| #[trigger] all_eq(a, s, e) ==> e - s != r)
    }

    #[effects(pure)]
    #[uses(all_eq, has_run, no_longer, no_longer_upto, run_ends)]
    fn longest_run(a: &[i64]) -> (r: usize)
        ensures has_run(a, r), no_longer(a, r),
    {
        let n: usize = a.len();
        if n == 0 {
            0
        } else {
            let mut best: usize = 1;
            let mut cur: usize = 1;
            let mut i: usize = 1;
            while i < n
                invariant n == a.len(), 1 <= i, i <= n, cur <= best, best <= i, run_ends(a, i, cur), has_run(a, best), no_longer_upto(a, i, best),
                decreases n - i,
            {
                if a[i] == a[i - 1] {
                    cur = cur + 1;
                } else {
                    cur = 1;
                }
                if cur > best {
                    best = cur;
                }
                i = i + 1;
            }
            best
        }
    }

    spec fn no_longer(a: &[i64], r: usize) -> bool {
        forall|s: usize, e: usize| #[trigger] all_eq(a, s, e) ==> e - s <= r
    }

    spec fn no_longer_upto(a: &[i64], i: usize, r: usize) -> bool {
        forall|s: usize, e: usize| e <= i && #[trigger] all_eq(a, s, e) ==> e - s <= r
