#[summary("sorting")]
mod tasks {
    spec fn is_min(a: &[i64], i: usize, j: usize, m: usize) -> bool {
        i <= m && m < j && j <= a.len() && (forall|k: usize| i <= k && k < j ==> a[m] <= #[trigger] a[k])
    }

    spec fn partitioned(a: &[i64], i: usize) -> bool {
        forall|k: usize, l: usize| k < i && i <= l && l < a.len() ==> #[trigger] a[k] <= #[trigger] a[l]
    }

    #[effects(pure)]
    #[uses(is_min, partitioned, sorted, sorted_prefix)]
    fn sort(a: &mut [i64]) -> ()
        ensures sorted(a),
    {
        let n: usize = a.len();
        let mut i: usize = 0;
        while i < n
            invariant n == a.len(), i <= n, sorted_prefix(a, i), partitioned(a, i),
            decreases n - i,
        {
            let mut m: usize = i;
            let mut j: usize = i + 1;
