                invariant n == a.len(), i < n, is_min(a, i, j, m), sorted_prefix(a, i), partitioned(a, i),
                decreases n - j,
            {
                if a[j] < a[m] {
                    m = j;
                }
                j = j + 1;
            }
            let t: i64 = a[i];
            a[i] = a[m];
            a[m] = t;
            i = i + 1;
        }
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|k: usize, l: usize| k < l && l < a.len() ==> #[trigger] a[k] <= #[trigger] a[l]
    }

    spec fn sorted_prefix(a: &[i64], i: usize) -> bool {
