#[summary("modular exponentiation")]
mod tasks {
    spec fn dom(base: i64, exp: i64, m: i64) -> bool {
        1 <= m && m <= 3000000000 && 0 <= base && 0 <= exp
    }

    spec fn mm_post(r: i64, x: i64, y: i64, m: i64) -> bool {
        r == mulm(x, y, m) && 0 <= r && r < m
    }

    spec fn mm_pre(x: i64, y: i64, m: i64) -> bool {
        1 <= m && m <= 3000000000 && 0 <= x && x < m && 0 <= y && y < m
    }

    spec fn mulm(x: i64, y: i64, m: i64) -> i64 {
        x * y % m
    }

    #[effects(pure)]
    #[uses(mm_post, mm_pre, mulm)]
    fn mulmod(x: i64, y: i64, m: i64) -> (r: i64)
        requires mm_pre(x, y, m),
        ensures mm_post(r, x, y, m),
    {
        let p: i64 = x * y;
        p % m
    }

    spec fn pm(b: i64, e: i64, m: i64) -> i64
        decreases e,
    {
        if e <= 0 {
            1 % m
        } else if e % 2 == 0 {
            pm(mulm(b, b, m), e / 2, m)
        } else {
            mulm(b, pm(mulm(b, b, m), e / 2, m), m)
        }
    }

    spec fn post(r: i64, base: i64, exp: i64, m: i64) -> bool {
        r == pm(base % m, exp, m) && 0 <= r && r < m
    }

    #[effects(pure)]
    #[uses(dom, post, rec_post, rec_pre)]
    fn pow_mod(base: i64, exp: i64, m: i64) -> (r: i64)
        requires dom(base, exp, m),
        ensures post(r, base, exp, m),
    {
        pow_rec(base % m, exp, m)
    }

    #[effects(pure)]
    #[uses(mm_post, mm_pre, pm, rec_post, rec_pre)]
    fn pow_rec(b: i64, e: i64, m: i64) -> (r: i64)
        requires rec_pre(b, e, m),
        ensures rec_post(r, b, e, m),
        decreases e,
    {
        if e == 0 {
            1 % m
        } else {
            let b2: i64 = tasks::mulmod(b, b, m);
            let h: i64 = pow_rec(b2, e / 2, m);
            if e % 2 == 0 {
                h
            } else {
                tasks::mulmod(b, h, m)
            }
        }
    }

    spec fn rec_post(r: i64, b: i64, e: i64, m: i64) -> bool {
        r == pm(b, e, m) && 0 <= r && r < m
    }

    spec fn rec_pre(b: i64, e: i64, m: i64) -> bool {
        1 <= m && m <= 3000000000 && 0 <= b && b < m && 0 <= e
    }
}
